#[derive(Debug, Clone)]
pub struct DebugInspectorPanelOptions {
    pub layout: LayoutStyle,
    pub selected_node: Option<String>,
    pub label_width: f32,
    pub row_height: f32,
    pub max_layout_rows: usize,
    pub max_animation_rows: usize,
    pub max_hitbox_rows: usize,
    pub max_overlap_rows: usize,
    pub show_animation: bool,
    pub show_geometry: bool,
    pub action_prefix: Option<String>,
    pub title_style: TextStyle,
}

impl Default for DebugInspectorPanelOptions {
    fn default() -> Self {
        Self {
            layout: LayoutStyle::from_taffy_style(Style {
                display: Display::Flex,
                flex_direction: FlexDirection::Column,
                size: TaffySize {
                    width: Dimension::percent(1.0),
                    height: Dimension::auto(),
                },
                gap: taffy::geometry::Size {
                    width: LengthPercentage::length(8.0),
                    height: LengthPercentage::length(8.0),
                },
                ..Default::default()
            }),
            selected_node: None,
            label_width: 128.0,
            row_height: 26.0,
            max_layout_rows: usize::MAX,
            max_animation_rows: 8,
            max_hitbox_rows: usize::MAX,
            max_overlap_rows: 8,
            show_animation: true,
            show_geometry: true,
            action_prefix: None,
            title_style: TextStyle {
                font_size: 14.0,
                line_height: 20.0,
                color: ColorRgba::new(238, 243, 248, 255),
                ..Default::default()
            },
        }
    }
}

