fn node_recommendation_record_value(record: &DebugNodeRecommendationRecord) -> String {
    let mut parts = Vec::new();
    if let Some(panel) = record.panels.first() {
        parts.push(format!("panel {panel}"));
    }
    if let Some(overlay) = record.overlays.first() {
        parts.push(format!("overlay {}", overlay.label()));
    }
    parts.push(format!("score {}", record.score));
    parts.push(record.status.label().to_owned());
    if !record.sources.is_empty() {
        parts.push(format!(
            "sources {}",
            record
                .sources
                .iter()
                .map(|source| source.label())
                .collect::<Vec<_>>()
                .join(", ")
        ));
    }
    if record.occurrence_count > 1 {
        parts.push(format!("{} clues", record.occurrence_count));
    }
    parts.push(record.summary.clone());
    parts.push(record.fix.clone());
    parts.join("; ")
}

