fn focus_navigation_timeline_record_row(
    index: usize,
    record: &DebugFocusNavigationTimelineRecord,
) -> PropertyGridRow {
    let mut row = row(
        format!("candidate.{index}"),
        record.name.clone(),
        focus_navigation_timeline_record_value(record),
    );
    row = match record.status {
        DebugFrameTraceStatus::Error => row.error(record.fix.clone()),
        DebugFrameTraceStatus::Warning => row.warning(record.fix.clone()),
        DebugFrameTraceStatus::Info => row.help(record.cause.clone()),
        DebugFrameTraceStatus::Ok => row.changed(),
    };
    row
}

fn focus_navigation_timeline_record_value(record: &DebugFocusNavigationTimelineRecord) -> String {
    let mut parts = vec![record.status.label().to_owned()];
    parts.push(format!("frames {}", record.frame_count));
    if record.focusable_frame_count > 0 {
        parts.push(format!("focusable {}", record.focusable_frame_count));
    }
    if record.focused_frame_count > 0 {
        parts.push(format!("focused {}", record.focused_frame_count));
    }
    if record.skipped_frame_count > 0 {
        parts.push(format!("skipped {}", record.skipped_frame_count));
    }
    if record.warning_frame_count > 0 {
        parts.push(format!("warnings {}", record.warning_frame_count));
    }
    if let Some(index) = record.latest_navigation_index {
        parts.push(format!("nav #{index}"));
    }
    if let Some(index) = record.latest_accessibility_index {
        parts.push(format!("a11y #{index}"));
    }
    if record.latest_clipped {
        parts.push("clipped".to_owned());
    }
    parts.push(record.fix.clone());
    parts.join("; ")
}

fn focus_navigation_timeline_frame_row(
    frame: &DebugFocusNavigationTimelineFrameRecord,
) -> PropertyGridRow {
    let mut row = row(
        format!("frame.{}", frame.index),
        frame.label.clone(),
        focus_navigation_timeline_frame_value(frame),
    );
    row = match frame.status {
        DebugFrameTraceStatus::Error => row.error(frame.fix.clone()),
        DebugFrameTraceStatus::Warning => row.warning(frame.fix.clone()),
        DebugFrameTraceStatus::Info => row.help(frame.cause.clone()),
        DebugFrameTraceStatus::Ok => row.changed(),
    };
    row
}

fn focus_navigation_timeline_frame_value(
    frame: &DebugFocusNavigationTimelineFrameRecord,
) -> String {
    let mut parts = vec![frame.status.label().to_owned()];
    if frame.focus_changed {
        parts.push("focus changed".to_owned());
    }
    parts.push(format!("focusable {}", frame.focusable_count));
    if let Some(focused) = &frame.focused_name {
        parts.push(format!("focused {focused}"));
    } else {
        parts.push("focused none".to_owned());
    }
    if frame.skipped_count > 0 {
        parts.push(format!("skipped {}", frame.skipped_count));
    }
    if frame.warning_count > 0 {
        parts.push(format!("warnings {}", frame.warning_count));
    }
    if frame.new_warning_count > 0 {
        parts.push(format!("new {}", frame.new_warning_count));
    }
    if frame.resolved_warning_count > 0 {
        parts.push(format!("resolved {}", frame.resolved_warning_count));
    }
    if let Some(top) = &frame.top_candidate_name {
        parts.push(format!("top {top}"));
    }
    parts.join("; ")
}

fn focus_candidate_label(candidate: &crate::debug::DebugFocusCandidate) -> String {
    let mut prefix = Vec::new();
    if candidate.current {
        prefix.push("current");
    }
    if candidate.next {
        prefix.push("next");
    }
    if candidate.previous {
        prefix.push("previous");
    }
    if prefix.is_empty() {
        candidate.name.clone()
    } else {
        format!("{} {}", prefix.join("/"), candidate.name)
    }
}

fn layout_rows(node: Option<&DebugLayoutInspectorNode>, max_rows: usize) -> Vec<PropertyGridRow> {
    let Some(node) = node else {
        return vec![row("empty", "Node", "No nodes in snapshot")];
    };
    let mut rows = vec![
        row("id", "ID", format!("#{}", node.id.0)),
        row("content", "Content", format!("{:?}", node.content_kind)),
        row("rect", "Rect", format_rect(node.rect)),
        row("clip", "Clip", format_rect(node.clip_rect)),
        row("final", "Final size", format_size(node.final_size)),
        row("children", "Children", node.children.len().to_string()),
        row("paint", "Paint items", node.paint.count.to_string()),
        row(
            "input",
            "Input",
            format!(
                "pointer={} focus={} keyboard={}",
                node.input.pointer, node.input.focusable, node.input.keyboard
            ),
        ),
        row(
            "action",
            "Action",
            node.action.clone().unwrap_or_else(|| "none".to_owned()),
        ),
        row("display", "Display", node.style.display.clone()),
        row("direction", "Direction", node.style.flex_direction.clone()),
        row("size", "Style size", node.style.size.clone()),
        row("min_size", "Min size", node.style.min_size.clone()),
        row("margin", "Margin", node.style.margin.clone()),
        row("padding", "Padding", node.style.padding.clone()),
        row("gap", "Gap", node.style.gap.clone()),
    ];
    if let Some(intrinsic) = node.intrinsic_size {
        rows.push(row(
            "intrinsic.min",
            "Intrinsic min",
            format_size(intrinsic.min),
        ));
        rows.push(row(
            "intrinsic.preferred",
            "Intrinsic pref",
            format_size(intrinsic.preferred),
        ));
    }
    if let Some(scroll) = node.scroll {
        rows.push(row(
            "scroll.offset",
            "Scroll offset",
            format_point(scroll.offset),
        ));
        rows.push(row(
            "scroll.viewport",
            "Scroll viewport",
            format_size(scroll.viewport_size),
        ));
        rows.push(row(
            "scroll.content",
            "Scroll content",
            format_size(scroll.content_size),
        ));
    }
    if let Some(scrollbar) = node.scrollbar {
        rows.push(row(
            "scrollbar.axis",
            "Scrollbar axis",
            format!("{:?}", scrollbar.axis),
        ));
        rows.push(row(
            "scrollbar.range",
            "Scrollbar range",
            format!(
                "viewport {:.1}, content {:.1}, max {:.1}",
                scrollbar.viewport(),
                scrollbar.content(),
                scrollbar.max_offset()
            ),
        ));
    }
    if let Some(accessibility) = &node.accessibility {
        rows.push(row(
            "accessibility",
            "Accessibility",
            format!(
                "{:?} {}",
                accessibility.role,
                accessibility.label.as_deref().unwrap_or("")
            ),
        ));
    }
    if !node.audit_warnings.is_empty() {
        rows.push(row(
            "audits",
            "Audit warnings",
            node.audit_warnings.len().to_string(),
        ));
    }
    rows.truncate(max_rows);
    rows
}

