fn overlap_timeline_record_row(
    index: usize,
    record: &DebugOverlapTimelineRecord,
) -> PropertyGridRow {
    let mut row = row(
        format!("frame.{index}"),
        record.label.clone(),
        overlap_timeline_record_value(record),
    );
    row = match record.status {
        DebugFrameTraceStatus::Error => row.error(record.fix.clone()),
        DebugFrameTraceStatus::Warning => row.warning(record.fix.clone()),
        DebugFrameTraceStatus::Info => row.help(record.cause.clone()),
        DebugFrameTraceStatus::Ok => row.changed(),
    };
    row
}

fn overlap_timeline_record_value(record: &DebugOverlapTimelineRecord) -> String {
    let mut parts = vec![format!(
        "{} overlap{}",
        record.overlap_count,
        plural_s(record.overlap_count)
    )];
    if record.interactive_overlap_count > 0 {
        parts.push(format!("interactive {}", record.interactive_overlap_count));
    }
    if record.new_overlap_count > 0 {
        parts.push(format!("new {}", record.new_overlap_count));
    }
    if record.resolved_overlap_count > 0 {
        parts.push(format!("resolved {}", record.resolved_overlap_count));
    }
    if record.persistent_overlap_count > 0 {
        parts.push(format!("persisting {}", record.persistent_overlap_count));
    }
    if let Some(kind) = record.top_kind {
        parts.push(overlap_kind_label(kind).to_owned());
    }
    if let Some(pair) = &record.top_pair {
        parts.push(pair.clone());
    }
    if record.top_overlap_area > 0.0 {
        parts.push(format!("{:.0}px2", record.top_overlap_area));
    }
    if let Some(change) = &record.previous_change {
        if change.changed_node_count > 0 {
            parts.push(format!("changes {}", change.changed_node_count));
        }
    }
    parts.push(record.fix.clone());
    parts.join("; ")
}

