fn frame_timing_waterfall_record_value(record: &DebugFrameTimingWaterfallRecord) -> String {
    let mut parts = Vec::new();
    if record.crosses_budget {
        parts.push("crosses budget".to_owned());
    } else if record.after_budget {
        parts.push("after budget".to_owned());
    }
    parts.extend([
        format!("inspect {}", record.inspect),
        format!(
            "{}-{}",
            format_duration_ms(record.start),
            format_duration_ms(record.end)
        ),
        format_duration_ms(record.duration),
    ]);
    if let Some(percent) = record.cumulative_percent_of_budget {
        parts.push(format!("{percent:.0}% budget"));
    }
    parts.push(record.fix.clone());
    parts.join("; ")
}

