fn frame_timeline_record_row(index: usize, record: &DebugFrameTimelineRecord) -> PropertyGridRow {
    let mut row = row(
        format!("frame.{index}"),
        record.label.clone(),
        frame_timeline_record_value(record),
    );
    row = match record.status {
        DebugFrameTraceStatus::Error => row.error(record.fix.clone()),
        DebugFrameTraceStatus::Warning => row.warning(record.fix.clone()),
        DebugFrameTraceStatus::Info => row.help(record.cause.clone()),
        DebugFrameTraceStatus::Ok => row.changed(),
    };
    row
}

fn frame_timeline_record_value(record: &DebugFrameTimelineRecord) -> String {
    let mut parts = vec![format_duration_ms(record.total)];
    if let Some(over_by) = record.over_budget_by {
        parts.push(format!("over {}", format_duration_ms(over_by)));
    }
    if let Some(change) = &record.previous_change {
        if change.changed_node_count > 0 {
            parts.push(format!("changes {}", change.changed_node_count));
            if change.layout_change_count > 0 {
                parts.push(format!("layout {}", change.layout_change_count));
            }
            if change.paint_change_count > 0 {
                parts.push(format!("paint {}", change.paint_change_count));
            }
            if change.animation_change_count > 0 {
                parts.push(format!("animation {}", change.animation_change_count));
            }
        }
    }
    if let Some(stage) = &record.slowest_stage {
        let duration = record
            .slowest_stage_duration
            .map(format_duration_ms)
            .unwrap_or_else(|| "unknown".to_owned());
        parts.push(format!("{stage} {duration}"));
    }
    if record.issue_count > 0 {
        parts.push(format!("issues {}", record.issue_count));
    }
    if !record.dirty_summary.is_empty() {
        parts.push(record.dirty_summary.clone());
    }
    parts.join("; ")
}

