fn why_trace_rows(trace: &DebugWhyTrace, max_reason_rows: usize) -> Vec<PropertyGridRow> {
    let mut summary = row("summary", "Summary", trace.summary.clone());
    summary = match trace.status {
        DebugFrameTraceStatus::Error => summary.error("Why trace has blocking clues"),
        DebugFrameTraceStatus::Warning => summary.warning("Why trace has clues to review"),
        DebugFrameTraceStatus::Info => summary.help("Why trace has explanatory clues"),
        DebugFrameTraceStatus::Ok => summary.changed(),
    };
    let trail = trace.trail();
    let overlay_plan = trace.overlay_plan();
    let mut rows = vec![
        summary,
        row("scope", "Scope", trace.scope.title()),
        row("subject", "Subject", trace.subject.clone()),
        row("status", "Status", trace.status.label()),
        row("clues", "Clues", trace.record_count.to_string()),
        row("review", "Review", trace.warning_count.to_string()),
        row(
            "overlays",
            "Overlays",
            why_overlay_layers_value(&trace.overlay_layers()),
        ),
        row("overlay-plan", "Overlay plan", overlay_plan.summary.clone()),
    ];
    if let Some(step) = trail.first() {
        rows.push(row(
            "next",
            "Next",
            format!(
                "{}; {}; {}",
                step.panel,
                why_primary_overlay_value(step),
                step.subject
            ),
        ));
    }
    for record in overlay_plan.records.iter().take(max_reason_rows) {
        rows.push(why_overlay_plan_record_row(record));
    }
    for step in trail.iter().take(max_reason_rows) {
        rows.push(why_trace_step_row(step));
    }
    rows
}

