fn why_timeline_record_value(record: &DebugWhyTimelineRecord) -> String {
    let mut parts = vec![format!(
        "{} clue{}",
        record.why_record_count,
        plural_s(record.why_record_count)
    )];
    if record.warning_count > 0 {
        parts.push(format!(
            "{} review{}",
            record.warning_count,
            plural_s(record.warning_count)
        ));
    }
    if let Some(panel) = &record.top_panel {
        parts.push(format!("open {panel}"));
    }
    if let Some(overlay) = record.primary_overlay {
        parts.push(format!("show {}", overlay.label()));
    }
    if let Some(subject) = &record.top_subject {
        parts.push(subject.clone());
    }
    parts.push(record.fix.clone());
    parts.join("; ")
}

fn why_timeline_overlay_layers_value(records: &[DebugWhyTimelineRecord]) -> String {
    let mut layers = Vec::new();
    for record in records {
        for layer in &record.overlay_layers {
            if !layers.contains(layer) {
                layers.push(*layer);
            }
        }
    }
    why_overlay_layers_value(&layers)
}

