fn debug_contract_rows(
    report: &DebugContractReport,
    max_check_rows: usize,
) -> Vec<PropertyGridRow> {
    let mut summary = row("summary", "Summary", report.summary.clone());
    summary = match report.status {
        DebugFrameTraceStatus::Error => summary.error("Debug contract has blocking failures"),
        DebugFrameTraceStatus::Warning => summary.warning("Debug contract has failed checks"),
        DebugFrameTraceStatus::Info => summary.help("Debug contract has notes or skipped checks"),
        DebugFrameTraceStatus::Ok => summary.changed(),
    };
    let mut rows = vec![
        summary,
        row("frame", "Frame", report.frame_label.clone()),
        row("status", "Status", report.status.label()),
        row("checks", "Checks", report.check_count.to_string()),
        row("passed", "Passed", report.pass_count.to_string()),
        row("failed", "Failed", report.fail_count.to_string()),
        row("skipped", "Skipped", report.skipped_count.to_string()),
        row("errors", "Errors", report.error_count.to_string()),
        row("warnings", "Warnings", report.warning_count.to_string()),
        row("info", "Info", report.info_count.to_string()),
    ];
    for check in report.checks.iter().take(max_check_rows) {
        rows.push(debug_contract_check_row(check));
    }
    rows
}

fn debug_contract_check_row(check: &DebugContractCheckRecord) -> PropertyGridRow {
    let state = if !check.checked {
        "skipped"
    } else if check.passed {
        "pass"
    } else {
        "fail"
    };
    let mut check_row = row(
        format!("check.{}", check.kind.label()),
        check.kind.title(),
        format!("{state}; {}; {}", check.summary, check.fix),
    );
    check_row = if !check.checked {
        check_row.help(check.cause.clone())
    } else {
        match check.status {
            DebugFrameTraceStatus::Error => check_row.error(check.cause.clone()),
            DebugFrameTraceStatus::Warning => check_row.warning(check.cause.clone()),
            DebugFrameTraceStatus::Info => check_row.help(check.cause.clone()),
            DebugFrameTraceStatus::Ok => check_row.changed(),
        }
    };
    check_row
}

