fn debug_invariant_record_value(record: &DebugInvariantRecord) -> String {
    let state = if !record.checked {
        "skipped"
    } else if record.passed {
        "pass"
    } else {
        "fail"
    };
    let mut parts = vec![state.to_owned(), record.summary.clone()];
    if record.issue_count > 0 {
        parts.push(format!(
            "{} issue{}",
            record.issue_count,
            plural_s(record.issue_count)
        ));
    }
    if !record.subjects.is_empty() {
        parts.push(format!("subjects {}", record.subjects.join(", ")));
    }
    parts.push(format!("open {}", record.panel));
    parts.push(record.fix.clone());
    parts.join("; ")
}

