fn root_cause_timeline_rows(
    trace: &DebugRootCauseTimelineTrace,
    max_cluster_rows: usize,
    max_frame_rows: usize,
) -> Vec<PropertyGridRow> {
    let mut summary = row("summary", "Summary", trace.summary.clone());
    summary = match trace.status {
        DebugFrameTraceStatus::Error => summary.error("Root-cause timeline has blocking clusters"),
        DebugFrameTraceStatus::Warning => {
            summary.warning("Root-cause timeline has clusters to review")
        }
        DebugFrameTraceStatus::Info => {
            summary.help("Root-cause timeline changed across retained frames")
        }
        DebugFrameTraceStatus::Ok => summary.changed(),
    };
    let mut rows = vec![
        summary,
        row("status", "Status", trace.status.label()),
        row("frames", "Frames", trace.frame_count.to_string()),
        row(
            "cluster_frames",
            "Cluster frames",
            trace.cluster_frame_count.to_string(),
        ),
        row("changed", "Changed", trace.changed_frame_count.to_string()),
        row("clusters", "Clusters", trace.cluster_count.to_string()),
        row("review", "Review", trace.warning_cluster_count.to_string()),
        row("clues", "Clues", trace.occurrence_count.to_string()),
        row("new", "New", trace.new_cluster_count.to_string()),
        row(
            "persistent",
            "Persistent",
            trace.persistent_cluster_count.to_string(),
        ),
        row(
            "resolved",
            "Resolved",
            trace.resolved_cluster_count.to_string(),
        ),
        row(
            "top_cluster",
            "Start with",
            trace
                .top_cluster
                .clone()
                .unwrap_or_else(|| "none".to_owned()),
        ),
        row(
            "top_action",
            "First action",
            trace
                .top_action
                .clone()
                .unwrap_or_else(|| "none".to_owned()),
        ),
    ];
    for (index, record) in trace.records.iter().take(max_cluster_rows).enumerate() {
        rows.push(root_cause_timeline_record_row(index, record));
    }
    for frame in trace.frames.iter().take(max_frame_rows) {
        rows.push(root_cause_timeline_frame_row(frame));
    }
    rows
}

