fn dirty_state_rows(
    explanation: &DirtyStateExplanation,
    max_subsystem_rows: usize,
    max_invalidation_rows: usize,
) -> Vec<PropertyGridRow> {
    let mut rows = Vec::new();
    let mut state = row("summary", "State", explanation.summary.clone());
    if explanation.clean {
        state = state.help("No recompute scheduled");
    } else {
        state = state.changed();
    }
    rows.push(state);

    let cause = explanation
        .primary_cause()
        .map(|cause| cause.summary.clone())
        .unwrap_or_else(|| "No runtime cause captured".to_owned());
    rows.push(row("cause", "Cause", cause));

    rows.push(row(
        "order",
        "Recompute",
        if explanation.recompute_order.is_empty() {
            "none".to_owned()
        } else {
            explanation
                .recompute_order
                .iter()
                .map(|subsystem| subsystem.display_label())
                .collect::<Vec<_>>()
                .join(", ")
        },
    ));

    for subsystem in explanation.active_subsystems().take(max_subsystem_rows) {
        let first_step = subsystem
            .recomputes
            .first()
            .map(String::as_str)
            .unwrap_or("recompute");
        let downstream = if subsystem.downstream.is_empty() {
            "none".to_owned()
        } else {
            subsystem.downstream.join(", ")
        };
        rows.push(
            row(
                format!("subsystem.{}", subsystem.subsystem.label()),
                subsystem.label.clone(),
                format!("{first_step}; affects {downstream}"),
            )
            .changed(),
        );
    }

    for (index, invalidation) in explanation
        .invalidations
        .iter()
        .take(max_invalidation_rows)
        .enumerate()
    {
        let flags = dirty_flag_list(invalidation.flags);
        rows.push(
            row(
                format!("invalidation.{index}"),
                invalidation.label.clone(),
                flags,
            )
            .changed(),
        );
    }

    rows
}

fn dirty_flag_list(flags: crate::DirtyFlags) -> String {
    let mut labels = Vec::new();
    if flags.layout {
        labels.push("layout");
    }
    if flags.paint {
        labels.push("paint");
    }
    if flags.input {
        labels.push("input");
    }
    if flags.theme {
        labels.push("theme");
    }
    if flags.text_measurement {
        labels.push("text_measurement");
    }
    if labels.is_empty() {
        "clean".to_owned()
    } else {
        labels.join(", ")
    }
}

