fn pointer_probe_candidate_row(
    index: usize,
    candidate: &DebugPointerProbeCandidate,
) -> PropertyGridRow {
    let mut row = row(
        format!("candidate.{index}"),
        candidate.name.clone(),
        pointer_probe_candidate_value(candidate),
    );
    row = match candidate.status {
        DebugNodeExplanationStatus::Error => row.error(candidate.fix.clone()),
        DebugNodeExplanationStatus::Warning => row.warning(candidate.fix.clone()),
        DebugNodeExplanationStatus::Info => row.help(candidate.fix.clone()),
        DebugNodeExplanationStatus::Ok => row.changed(),
    };
    row
}

fn pointer_probe_candidate_value(candidate: &DebugPointerProbeCandidate) -> String {
    let mut parts = Vec::new();
    if candidate.target {
        parts.push("target".to_owned());
    } else if candidate.hit {
        parts.push("raw hit".to_owned());
    } else if candidate.effective_hit {
        parts.push("effective hit".to_owned());
    } else if candidate.layout_contains_point {
        parts.push("layout hit".to_owned());
    } else if candidate.clip_contains_point {
        parts.push("clip hit".to_owned());
    } else {
        parts.push("near point".to_owned());
    }
    if !candidate.rejections.is_empty() {
        parts.push(
            candidate
                .rejections
                .iter()
                .map(event_route_rejection_label)
                .collect::<Vec<_>>()
                .join(", "),
        );
    } else {
        parts.push(candidate.cause.clone());
    }
    if let Some(action) = &candidate.action {
        parts.push(action.clone());
    }
    parts.join("; ")
}

fn pointer_probe_node_label(name: Option<&str>, node: Option<UiNodeId>) -> String {
    name.map(str::to_owned)
        .or_else(|| node.map(|node| format!("#{}", node.0)))
        .unwrap_or_else(|| "none".to_owned())
}

