fn hit_target_record_row(index: usize, target: &DebugHitTargetRecord) -> PropertyGridRow {
    let mut row = row(
        format!("target.{index}"),
        target.name.clone(),
        hit_target_record_value(target),
    );
    row = match target.status {
        DebugFrameTraceStatus::Error => row.error(target.fix.clone()),
        DebugFrameTraceStatus::Warning => row.warning(target.fix.clone()),
        DebugFrameTraceStatus::Info => row.help(target.cause.clone()),
        DebugFrameTraceStatus::Ok => row.changed(),
    };
    row
}

fn hit_target_record_value(target: &DebugHitTargetRecord) -> String {
    let mut parts = Vec::new();
    if target.hit_rect.is_none() {
        parts.push("missing hit rect".to_owned());
    } else if target.min_dimension < 24.0 {
        parts.push("small hit target".to_owned());
    } else if target.clipped {
        parts.push("clipped hit target".to_owned());
    } else {
        parts.push("hit target".to_owned());
    }
    parts.push(format!("{:.0}x{:.0}", target.hit_width, target.hit_height));
    if !target.rejections.is_empty() {
        parts.push(
            target
                .rejections
                .iter()
                .map(|rejection| format!("{rejection:?}"))
                .collect::<Vec<_>>()
                .join(", "),
        );
    } else {
        parts.push(target.summary.clone());
    }
    parts.push(target.fix.clone());
    parts.join("; ")
}

