fn hitbox_occlusion_timeline_record_value(record: &DebugHitboxOcclusionTimelineRecord) -> String {
    let mut parts = vec![format!("frames {}", record.frame_count)];
    if record.blocked_frame_count > 0 {
        parts.push(format!("blocked {}", record.blocked_frame_count));
    }
    if record.warning_frame_count > 0 {
        parts.push(format!("warnings {}", record.warning_frame_count));
    }
    parts.push(format!("max {:.0}%", record.max_occluded_ratio * 100.0));
    parts.push(format!(
        "latest {:.0}%",
        record.latest_occluded_ratio * 100.0
    ));
    if record.max_occluder_count > 0 {
        parts.push(format!("occluders {}", record.max_occluder_count));
    }
    if let Some(name) = &record.latest_top_occluder_name {
        parts.push(format!("top {name}"));
    }
    if let Some(frame) = &record.latest_frame_label {
        parts.push(format!("latest {frame}"));
    }
    parts.join("; ")
}

