fn interaction_state_node_label(name: Option<&str>, node: Option<UiNodeId>) -> String {
    name.map(str::to_owned)
        .or_else(|| node.map(|node| format!("#{}", node.0)))
        .unwrap_or_else(|| "none".to_owned())
}

fn interaction_state_record_row(
    index: usize,
    record: &DebugInteractionStateRecord,
) -> PropertyGridRow {
    let mut row = row(
        format!("interaction.{index}"),
        record.name.clone(),
        interaction_state_record_value(record),
    );
    row = match record.status {
        DebugFrameTraceStatus::Error => row.error(record.fix.clone()),
        DebugFrameTraceStatus::Warning => row.warning(record.fix.clone()),
        DebugFrameTraceStatus::Info => row.help(record.cause.clone()),
        DebugFrameTraceStatus::Ok => row.changed(),
    };
    row
}

fn interaction_state_record_value(record: &DebugInteractionStateRecord) -> String {
    let mut parts = Vec::new();
    if record.roles.is_empty() {
        parts.push("inactive".to_owned());
    } else {
        parts.push(record.roles.join(", "));
    }
    let mut flags = Vec::new();
    if record.visible {
        flags.push("visible");
    } else {
        flags.push("hidden");
    }
    if record.pointer {
        flags.push("pointer");
    }
    if record.focusable {
        flags.push("focusable");
    }
    parts.push(flags.join("/"));
    if record.paint_count > 0 {
        parts.push(format!("paint {}", record.paint_count));
    }
    parts.join("; ")
}

