fn interaction_affordance_timeline_record_value(
    record: &DebugInteractionAffordanceTimelineRecord,
) -> String {
    let mut parts = vec![format!("frames {}", record.frame_count)];
    if record.issue_frame_count > 0 {
        parts.push(format!("issue {}", record.issue_frame_count));
    }
    if record.warning_frame_count > 0 {
        parts.push(format!("warnings {}", record.warning_frame_count));
    }
    if record.average_score > 0.0 {
        parts.push(format!("avg {:.1}", record.average_score));
    }
    if record.max_score > 0 {
        parts.push(format!("max {}", record.max_score));
    }
    if !record.latest_issues.is_empty() {
        parts.push(
            record
                .latest_issues
                .iter()
                .map(|issue| issue.label())
                .collect::<Vec<_>>()
                .join(", "),
        );
    }
    if let Some(binding) = &record.latest_binding {
        parts.push(format!("binding {binding}"));
    } else if record.latest_pointer || record.latest_focusable || record.latest_keyboard {
        parts.push("no binding".to_owned());
    }
    let input = interaction_affordance_timeline_input_value(record);
    if !input.is_empty() {
        parts.push(format!("input {input}"));
    }
    if record.latest_effective_hit {
        parts.push("hit".to_owned());
    }
    if !record.latest_accessibility_present {
        parts.push("no a11y".to_owned());
    }
    if let Some(panel) = record.latest_panels.first() {
        parts.push(format!("panel {panel}"));
    }
    parts.join("; ")
}

