fn paint_order_rows(trace: &DebugPaintOrderTrace, max_stack_rows: usize) -> Vec<PropertyGridRow> {
    let mut summary = row("summary", "Summary", trace.summary.clone());
    summary = match trace.status {
        DebugNodeExplanationStatus::Error => summary.error("Paint order has blocking issues"),
        DebugNodeExplanationStatus::Warning => summary.warning("Paint order needs review"),
        DebugNodeExplanationStatus::Info => summary.help("Paint stack has explanatory details"),
        DebugNodeExplanationStatus::Ok => summary.changed(),
    };
    let mut rows = vec![
        summary,
        row("status", "Status", trace.status.label()),
        row("point", "Point", format_point(trace.point)),
        row("paint", "Paint items", trace.item_count.to_string()),
        row(
            "top",
            "Top visible",
            paint_order_node_label(trace.top_visible_name.as_deref(), trace.top_visible_node),
        ),
        row("stack", "Stack rows", trace.stack.len().to_string()),
    ];

    for (index, item) in trace.stack.iter().take(max_stack_rows).enumerate() {
        rows.push(paint_order_stack_row(index, item));
    }

    rows
}

fn paint_order_stack_row(index: usize, item: &DebugPaintStackItem) -> PropertyGridRow {
    let mut row = row(
        format!("stack.{index}"),
        item.node_name
            .clone()
            .unwrap_or_else(|| format!("#{}", item.node.0)),
        paint_order_stack_value(item),
    );
    if item.visible_at_point && index == 0 {
        row = row.changed();
    } else if item.visible_at_point {
        row = row.help("Visible at the point but covered by earlier stack rows");
    } else {
        row = row.warning(item.fix.clone());
    }
    row
}

fn paint_order_stack_value(item: &DebugPaintStackItem) -> String {
    let mut parts = vec![format!(
        "{} z={} layer={:?}",
        item.kind, item.resolved_z, item.layer
    )];
    if item.visible_at_point {
        parts.push("visible".to_owned());
    } else if !item.clip_contains_point {
        parts.push("clipped".to_owned());
    } else {
        parts.push("transparent".to_owned());
    }
    if !item.rect_contains_point && item.bounds_contains_point {
        parts.push("outset".to_owned());
    }
    if let Some(shader) = &item.shader_key {
        parts.push(format!("shader={shader}"));
    }
    parts.join("; ")
}

fn paint_order_node_label(name: Option<&str>, node: Option<UiNodeId>) -> String {
    name.map(str::to_owned)
        .or_else(|| node.map(|node| format!("#{}", node.0)))
        .unwrap_or_else(|| "none".to_owned())
}

