fn visual_effect_rows(
    trace: &DebugVisualEffectTrace,
    max_effect_rows: usize,
) -> Vec<PropertyGridRow> {
    let mut summary = row("summary", "Summary", trace.summary.clone());
    if trace.issue_count > 0 {
        summary = summary.warning("Visual effects need bounds review");
    } else if trace.effect_count > 0 {
        summary = summary.help("Visual effect contracts are present");
    } else {
        summary = summary.changed();
    }
    let mut rows = vec![
        summary,
        row("effects", "Effects", trace.effect_count.to_string()),
        row("issues", "Review", trace.issue_count.to_string()),
        row(
            "selected",
            "Selected",
            trace
                .selected_name
                .clone()
                .unwrap_or_else(|| "none".to_owned()),
        ),
    ];

    for (index, effect) in trace.records.iter().take(max_effect_rows).enumerate() {
        rows.push(visual_effect_row(index, effect));
    }

    rows
}

fn visual_effect_row(index: usize, effect: &DebugVisualEffectRecord) -> PropertyGridRow {
    let mut row = row(
        format!("effect.{index}"),
        effect.name.clone(),
        visual_effect_value(effect),
    );
    row = match effect.status {
        DebugFrameTraceStatus::Error => row.error(effect.cause.clone()),
        DebugFrameTraceStatus::Warning => row.warning(effect.cause.clone()),
        DebugFrameTraceStatus::Info => row.help(effect.cause.clone()),
        DebugFrameTraceStatus::Ok => row.changed(),
    };
    row
}

fn visual_effect_value(effect: &DebugVisualEffectRecord) -> String {
    let mut parts = vec![effect.summary.clone()];
    if effect.paint_outside_hit {
        parts.push("reserve margin or adjust hit".to_owned());
    } else if effect.hit_outside_paint {
        parts.push("visible affordance missing".to_owned());
    } else if effect.clipped {
        parts.push("clip trims effect".to_owned());
    } else if effect.paint_outside_layout {
        parts.push("reserve outer margin".to_owned());
    }
    if let Some(material) = &effect.material {
        parts.push(material.clone());
    }
    parts.join("; ")
}

