fn text_input_state_rows(trace: &DebugTextInputStateTrace) -> Vec<PropertyGridRow> {
    let mut summary = row("summary", "Summary", trace.summary.clone());
    summary = match trace.status {
        DebugFrameTraceStatus::Error => summary.error("Text input state has blocking issues"),
        DebugFrameTraceStatus::Warning => summary.warning("Text input state needs review"),
        DebugFrameTraceStatus::Info => summary.help("Text input state has active edit context"),
        DebugFrameTraceStatus::Ok => summary.changed(),
    };
    vec![
        summary,
        row("status", "Status", trace.status.label()),
        row("text", "Text", text_input_state_text_value(trace)),
        row("bytes", "Bytes", trace.byte_len.to_string()),
        row("chars", "Characters", trace.char_count.to_string()),
        row("lines", "Lines", trace.line_count.to_string()),
        row(
            "mode",
            "Mode",
            if trace.multiline {
                "multiline"
            } else {
                "single line"
            },
        ),
        row(
            "caret",
            "Caret",
            format!(
                "byte {}; line {}; col {}",
                trace.caret,
                trace.caret_line + 1,
                trace.caret_column + 1
            ),
        ),
        row(
            "selection",
            "Selection",
            text_input_state_selection_value(trace),
        ),
        row(
            "composition",
            "Composition",
            text_input_state_composition_value(trace),
        ),
        row(
            "history",
            "History",
            format!("undo {}; redo {}", trace.undo_depth, trace.redo_depth),
        ),
        row(
            "boundary",
            "Boundary",
            format!("start={} end={}", trace.caret_at_start, trace.caret_at_end),
        ),
        row("cause", "Cause", trace.cause.clone()),
        row("fix", "Fix", trace.fix.clone()),
    ]
}

fn text_input_state_text_value(trace: &DebugTextInputStateTrace) -> String {
    if trace.text_preview_truncated {
        format!("{} (truncated)", trace.text_preview)
    } else if trace.text_preview.is_empty() {
        "empty".to_owned()
    } else {
        trace.text_preview.clone()
    }
}

fn text_input_state_selection_value(trace: &DebugTextInputStateTrace) -> String {
    let Some((start, end)) = trace.selection_range else {
        if let Some(anchor) = trace.selection_anchor {
            return format!("collapsed anchor {anchor}");
        }
        return "none".to_owned();
    };
    let mut parts = vec![format!(
        "{start}..{end}; {} chars",
        trace.selected_char_count
    )];
    if let Some(text) = &trace.selected_text_preview {
        if !text.is_empty() {
            parts.push(text.clone());
        }
    }
    parts.join("; ")
}

fn text_input_state_composition_value(trace: &DebugTextInputStateTrace) -> String {
    let Some(text) = &trace.composing_text else {
        return "none".to_owned();
    };
    if text.is_empty() {
        "none".to_owned()
    } else {
        format!("{} chars; {}", trace.composing_char_count, text)
    }
}

fn text_input_event_rows(
    trace: &DebugTextInputEventTrace,
    max_platform_request_rows: usize,
) -> Vec<PropertyGridRow> {
    let mut summary = row("summary", "Summary", trace.summary.clone());
    summary = match trace.status {
        DebugFrameTraceStatus::Error => summary.error("Text input event has blocking issues"),
        DebugFrameTraceStatus::Warning => summary.warning("Text input event needs review"),
        DebugFrameTraceStatus::Info => summary.help("Text input event has explanatory details"),
        DebugFrameTraceStatus::Ok => summary.changed(),
    };
    let mut rows = vec![
        summary,
        row("status", "Status", trace.status.label()),
        row("focus", "Focus", text_input_event_focus_value(trace)),
        row(
            "consumed",
            "Consumed",
            text_input_event_consumed_value(trace),
        ),
        row(
            "policy",
            "Policy",
            text_input_event_policy_value(&trace.policy),
        ),
        row("edit", "Edit", text_input_event_edit_value(trace)),
        row(
            "clipboard",
            "Clipboard",
            trace
                .clipboard_action
                .clone()
                .unwrap_or_else(|| "none".to_owned()),
        ),
        row(
            "transaction",
            "Transaction",
            text_input_event_transaction_value(trace),
        ),
        row("history", "History", text_input_event_history_value(trace)),
        row(
            "requests",
            "Requests",
            trace.platform_request_count.to_string(),
        ),
        row("cause", "Cause", trace.cause.clone()),
        row("fix", "Fix", trace.fix.clone()),
    ];

    for request in trace
        .platform_requests
        .iter()
        .take(max_platform_request_rows)
    {
        rows.push(text_input_platform_request_row(request));
    }
    rows
}

fn text_input_event_focus_value(trace: &DebugTextInputEventTrace) -> String {
    let mut parts = vec![format!("focused={}", trace.focused)];
    if let Some(node) = trace.focused_node {
        parts.push(format!("node {}", node.0));
    }
    if let Some(node) = trace.hovered {
        parts.push(format!("hover {}", node.0));
    }
    if let Some(node) = trace.pressed {
        parts.push(format!("press {}", node.0));
    }
    parts.join("; ")
}

fn text_input_event_consumed_value(trace: &DebugTextInputEventTrace) -> String {
    if trace.input_consumed {
        trace
            .consumed_by
            .map(|node| format!("yes; node {}", node.0))
            .unwrap_or_else(|| "yes".to_owned())
    } else {
        "no".to_owned()
    }
}

fn text_input_event_policy_value(policy: &Option<DebugTextInputPolicyTrace>) -> String {
    let Some(policy) = policy else {
        return "unknown".to_owned();
    };
    let mut parts = vec![policy.status.label().to_owned()];
    if !policy.enabled {
        parts.push("disabled".to_owned());
    }
    if policy.read_only {
        parts.push("read only".to_owned());
    }
    if !policy.selectable {
        parts.push("not selectable".to_owned());
    }
    if !policy.allow_copy {
        parts.push("copy disabled".to_owned());
    }
    parts.push(format!(
        "edit={} select={} copy={}",
        policy.can_edit, policy.can_select, policy.can_copy
    ));
    parts.join("; ")
}

fn text_input_event_edit_value(trace: &DebugTextInputEventTrace) -> String {
    if !trace.has_edit {
        return "none".to_owned();
    }
    let mut parts = vec![trace.phase.clone().unwrap_or_else(|| "unknown".to_owned())];
    if trace.changed {
        parts.push("changed".to_owned());
    }
    if trace.committed {
        parts.push("committed".to_owned());
    }
    if trace.canceled {
        parts.push("canceled".to_owned());
    }
    parts.join("; ")
}

fn text_input_event_transaction_value(trace: &DebugTextInputEventTrace) -> String {
    let Some(id) = &trace.transaction_id else {
        return "none".to_owned();
    };
    let mut parts = vec![id.clone()];
    if let Some(phase) = &trace.transaction_phase {
        parts.push(phase.clone());
    }
    if let Some(target) = &trace.transaction_target {
        parts.push(target.clone());
    }
    if let (Some(before), Some(after)) = (
        trace.transaction_before_char_count,
        trace.transaction_after_char_count,
    ) {
        parts.push(format!("{before}->{after} chars"));
    }
    parts.join("; ")
}

fn text_input_event_history_value(trace: &DebugTextInputEventTrace) -> String {
    let Some(id) = &trace.history_apply_id else {
        return "none".to_owned();
    };
    let mut parts = vec![id.clone()];
    if let Some(direction) = &trace.history_apply_direction {
        parts.push(direction.clone());
    }
    if let Some(chars) = trace.history_apply_text_char_count {
        parts.push(format!("{chars} chars"));
    }
    parts.join("; ")
}

fn text_input_platform_request_row(
    request: &DebugTextInputPlatformRequestRecord,
) -> PropertyGridRow {
    row(
        format!("request.{}", request.index),
        format!("Request {}", request.index + 1),
        format!("{}; {}", request.kind, request.detail),
    )
    .help("Platform request emitted by the text input event")
}

