fn text_localization_record_row(
    index: usize,
    record: &DebugTextLocalizationRecord,
) -> PropertyGridRow {
    let mut row = row(
        format!("text.{index}"),
        record.name.clone(),
        text_localization_record_value(record),
    );
    row = match record.status {
        DebugFrameTraceStatus::Error => row.error(record.fix.clone()),
        DebugFrameTraceStatus::Warning => row.warning(record.fix.clone()),
        DebugFrameTraceStatus::Info => row.help(record.cause.clone()),
        DebugFrameTraceStatus::Ok => row.changed(),
    };
    row
}

fn text_localization_record_value(record: &DebugTextLocalizationRecord) -> String {
    let mut parts = vec![record.status.label().to_owned()];
    if record.dynamic_label {
        parts.push(
            record
                .dynamic_key
                .as_ref()
                .map(|key| format!("dynamic {key}"))
                .unwrap_or_else(|| "dynamic".to_owned()),
        );
    }
    if let Some(locale) = &record.locale {
        parts.push(format!("locale {locale}"));
    }
    parts.push(format!("dir {}", record.direction));
    parts.push(format!("bidi {}", record.bidi));
    if record.uses_intrinsic_text {
        parts.push(format!("measure {} chars", record.measurement_char_count));
    } else if record.dynamic_label || record.locale.is_some() || record.direction == "Rtl" {
        parts.push("missing intrinsic".to_owned());
    }
    parts.push(record.fix.clone());
    parts.join("; ")
}

