fn scroll_range_record_value(record: &DebugScrollRangeRecord) -> String {
    let mut parts = Vec::new();
    parts.push(format!(
        "range h {:.0} v {:.0}",
        record.horizontal_range, record.vertical_range
    ));
    if let Some(offset) = record.offset {
        parts.push(format!(
            "offset {}/{}",
            format_point(offset),
            record
                .max_offset
                .map(format_point)
                .unwrap_or_else(|| "none".to_owned())
        ));
    }
    if record.horizontal_overflow {
        parts.push("horizontal overflow".to_owned());
    }
    if record.vertical_overflow {
        parts.push("vertical overflow".to_owned());
    }
    if record.has_scrollbar {
        parts.push("scrollbar".to_owned());
    }
    if record.offset_out_of_range {
        parts.push("offset out of range".to_owned());
    }
    parts.join("; ")
}

