fn frame_diff_rows(diff: &DebugFrameDiff, max_change_rows: usize) -> Vec<PropertyGridRow> {
    let mut summary = row("summary", "Summary", diff.summary());
    if diff.is_empty() {
        summary = summary.help("No changes detected");
    } else {
        summary = summary.changed();
    }
    let mut rows = vec![
        summary,
        row("changed", "Changed", diff.changed_count().to_string()),
        row("added", "Added", diff.added_count().to_string()),
        row("removed", "Removed", diff.removed_count().to_string()),
        row(
            "nodes",
            "Node count",
            format!("{} -> {}", diff.before_node_count, diff.after_node_count),
        ),
    ];

    for change in diff.changed_nodes.iter().take(max_change_rows) {
        rows.push(frame_diff_change_row(change));
    }

    rows
}

fn frame_diff_change_row(change: &DebugFrameNodeChange) -> PropertyGridRow {
    let mut row = row(
        format!("node.{}", animation_graph_action_id_part(&change.name)),
        change.name.clone(),
        frame_diff_change_value(change),
    );
    if change.kinds.iter().any(|kind| {
        matches!(
            kind,
            crate::debug::DebugFrameChangeKind::Added
                | crate::debug::DebugFrameChangeKind::Removed
                | crate::debug::DebugFrameChangeKind::Layout
                | crate::debug::DebugFrameChangeKind::Hitbox
        )
    }) {
        row = row.warning(change.summary());
    } else {
        row = row.changed();
    }
    row
}

fn frame_diff_change_value(change: &DebugFrameNodeChange) -> String {
    let detail = change
        .details
        .first()
        .cloned()
        .unwrap_or_else(|| change.summary());
    format!("{}: {detail}", change.summary())
}

