fn constraint_issue_rows(
    report: &DebugConstraintReport,
    max_issue_rows: usize,
) -> Vec<PropertyGridRow> {
    let mut summary = row("summary", "Summary", report.summary());
    if report.issues.is_empty() {
        summary = summary.help("No constraint issues detected");
    } else if report.count_by_severity(DebugConstraintSeverity::Error) > 0 {
        summary = summary.error("Blocking constraint issue");
    } else {
        summary = summary.warning("Needs review");
    }
    let mut rows = vec![
        summary,
        row("total", "Total", report.issues.len().to_string()),
        row(
            "errors",
            "Errors",
            report
                .count_by_severity(DebugConstraintSeverity::Error)
                .to_string(),
        ),
        row(
            "warnings",
            "Warnings",
            report
                .count_by_severity(DebugConstraintSeverity::Warning)
                .to_string(),
        ),
    ];

    for (index, issue) in report.issues.iter().take(max_issue_rows).enumerate() {
        rows.push(constraint_issue_row(index, issue));
    }

    rows
}

fn constraint_issue_row(index: usize, issue: &DebugConstraintIssue) -> PropertyGridRow {
    let label = issue
        .name
        .clone()
        .unwrap_or_else(|| issue.kind.label().to_owned());
    let mut row = row(
        format!("issue.{index}"),
        label,
        format!("{}: {}", issue.kind.label(), issue.fix),
    );
    match issue.severity {
        DebugConstraintSeverity::Error => row = row.error(issue.summary.clone()),
        DebugConstraintSeverity::Warning => row = row.warning(issue.summary.clone()),
        DebugConstraintSeverity::Info => row = row.help(issue.summary.clone()),
    }
    row
}

fn resource_diagnostics_rows(
    report: &DebugResourceReport,
    max_resource_rows: usize,
) -> Vec<PropertyGridRow> {
    let mut summary = row("summary", "Summary", report.summary());
    if report.records.is_empty() {
        summary = summary.help("No image, texture, or canvas resources referenced");
    } else if report.invalid_count() > 0 {
        summary = summary.error("Invalid resource update");
    } else if report.missing_count() > 0 || report.unused_update_count() > 0 {
        summary = summary.warning("Resource state needs review");
    } else {
        summary = summary.changed();
    }
    let mut rows = vec![
        summary,
        row("total", "Total", report.records.len().to_string()),
        row(
            "updated",
            "Updated",
            report
                .count_by_status(DebugResourceStatus::Updated)
                .to_string(),
        ),
        row("missing", "Missing", report.missing_count().to_string()),
        row("invalid", "Invalid", report.invalid_count().to_string()),
        row("unused", "Unused", report.unused_update_count().to_string()),
    ];

    for (index, record) in report.records.iter().take(max_resource_rows).enumerate() {
        rows.push(resource_diagnostics_row(index, record));
    }

    rows
}

fn resource_diagnostics_row(index: usize, record: &DebugResourceRecord) -> PropertyGridRow {
    let mut row = row(
        format!("resource.{index}"),
        record.handle_label(),
        format!("{}: {}", record.status.label(), record.fix),
    );
    match record.status {
        DebugResourceStatus::Invalid => row = row.error(record.summary.clone()),
        DebugResourceStatus::Missing | DebugResourceStatus::UnusedUpdate => {
            row = row.warning(record.summary.clone());
        }
        DebugResourceStatus::Unresolved => row = row.help(record.summary.clone()),
        DebugResourceStatus::Updated => row = row.changed(),
        DebugResourceStatus::Resolved => {}
    }
    row
}

