fn resource_timeline_record_value(record: &DebugResourceTimelineRecord) -> String {
    let mut parts = vec![record.status.label().to_owned()];
    parts.push(format!("frames {}", record.frame_count));
    if record.issue_frame_count > 0 {
        parts.push(format!("issues {}", record.issue_frame_count));
    }
    parts.push(format!("latest {}", record.latest_status.label()));
    if let Some(issue) = record.latest_issue {
        parts.push(issue.label().to_owned());
    }
    if record.missing_frame_count > 0 {
        parts.push(format!("missing {}", record.missing_frame_count));
    }
    if record.invalid_frame_count > 0 {
        parts.push(format!("invalid {}", record.invalid_frame_count));
    }
    if record.unused_update_frame_count > 0 {
        parts.push(format!("unused {}", record.unused_update_frame_count));
    }
    if record.unresolved_frame_count > 0 {
        parts.push(format!("unresolved {}", record.unresolved_frame_count));
    }
    parts.push(record.fix.clone());
    parts.join("; ")
}

