fn node_explanation_rows(
    explanation: &DebugNodeExplanation,
    max_overlap_rows: usize,
    max_constraint_rows: usize,
    max_resource_rows: usize,
) -> Vec<PropertyGridRow> {
    let mut summary = row("summary", "Summary", explanation.summary.clone());
    summary = match explanation.status {
        DebugNodeExplanationStatus::Error => summary.error("Node has blocking debug issues"),
        DebugNodeExplanationStatus::Warning => summary.warning("Node needs review"),
        DebugNodeExplanationStatus::Info => summary.help("Node has explanatory details"),
        DebugNodeExplanationStatus::Ok => summary.changed(),
    };
    let mut rows = vec![
        summary,
        row("status", "Status", explanation.status.label()),
        row("node", "Node", explanation.name.clone()),
        row("layout", "Layout cause", explanation.layout.cause.clone()),
        row(
            "size",
            "Size",
            format!(
                "{} from {}",
                format_size(explanation.layout.final_size),
                explanation.layout.style_size
            ),
        ),
        row("clip", "Clip", format_rect(explanation.layout.clip_rect)),
        row(
            "geometry",
            "Geometry cause",
            explanation.geometry.cause.clone(),
        ),
        row(
            "hit",
            "Hit rect",
            optional_rect(explanation.geometry.hit_rect),
        ),
        row("input", "Input", explanation.input.route_summary.clone()),
    ];

    if let Some(route) = &explanation.route {
        let mut route_row = row("route", "Route", route.summary.clone());
        if route.selected {
            route_row = route_row.changed();
        } else if !route.rejections.is_empty() {
            route_row = route_row.warning(route.cause.clone());
        } else {
            route_row = route_row.help(route.cause.clone());
        }
        rows.push(route_row);
    }

    rows.push(row(
        "constraints",
        "Constraints",
        explanation.constraints.len().to_string(),
    ));
    for (index, issue) in explanation
        .constraints
        .iter()
        .take(max_constraint_rows)
        .enumerate()
    {
        rows.push(node_explanation_constraint_row(index, issue));
    }

    rows.push(row(
        "overlaps",
        "Overlaps",
        explanation.overlaps.len().to_string(),
    ));
    for (index, overlap) in explanation
        .overlaps
        .iter()
        .take(max_overlap_rows)
        .enumerate()
    {
        rows.push(node_explanation_overlap_row(index, overlap));
    }

    rows.push(row(
        "resources",
        "Resources",
        explanation.resources.len().to_string(),
    ));
    for (index, resource) in explanation
        .resources
        .iter()
        .take(max_resource_rows)
        .enumerate()
    {
        rows.push(node_explanation_resource_row(index, resource));
    }

    rows
}

