    #[test]
    fn point_autopsy_overlay_draws_point_target_and_overlap() {
        let mut source = UiDocument::new(root_style(200.0, 120.0));
        source.add_child(
            source.root,
            UiNode::container("back", LayoutStyle::size(92.0, 36.0))
                .with_input(InputBehavior::BUTTON)
                .with_action("back.activate")
                .with_visual(UiVisual::panel(ColorRgba::new(20, 80, 140, 255), None, 0.0)),
        );
        source.add_child(
            source.root,
            UiNode::container(
                "front",
                UiNodeStyle::new(crate::layout::absolute(20.0, 0.0, 92.0, 36.0)).with_z_index(8.0),
            )
            .with_input(InputBehavior::BUTTON)
            .with_action("front.activate")
            .with_visual(UiVisual::panel(ColorRgba::new(120, 70, 35, 255), None, 0.0)),
        );
        source
            .compute_layout(UiSize::new(200.0, 120.0), &mut ApproxTextMeasurer)
            .expect("source layout");
        let trace = DebugPointAutopsyTrace::pointer_down(
            &source,
            &mut ApproxTextMeasurer,
            UiPoint::new(30.0, 10.0),
        );

        let mut doc = UiDocument::new(root_style(240.0, 160.0));
        let root = doc.root;
        let overlay = point_autopsy_overlay(
            &mut doc,
            root,
            "debug.point.visual",
            &trace,
            PointAutopsyOverlayOptions::default().with_action_prefix("debug.point.visual"),
        );
        doc.compute_layout(UiSize::new(240.0, 160.0), &mut ApproxTextMeasurer)
            .expect("point overlay layout");

        assert_eq!(doc.node(overlay.root).name, "debug.point.visual");
        assert_eq!(doc.node(overlay.point).name, "debug.point.visual.point");
        assert!(overlay
            .target_bounds
            .iter()
            .any(|id| doc.node(*id).name == "debug.point.visual.target.hit"));
        assert!(overlay.overlap.is_some_and(|id| {
            doc.node(id).name == "debug.point.visual.overlap"
                && doc
                    .node(id)
                    .action
                    .as_ref()
                    .and_then(|action| action.action_id())
                    .is_some_and(|action| action.as_str() == "debug.point.visual.overlap")
        }));
        assert_eq!(
            doc.node(overlay.point)
                .action
                .as_ref()
                .and_then(|action| action.action_id())
                .map(|id| id.as_str()),
            Some("debug.point.visual.point")
        );
        assert!(!overlay.labels.is_empty());
    }

