    #[test]
    fn slow_frame_panel_links_timing_to_node_causes() {
        let mut source = UiDocument::new(root_style(220.0, 140.0));
        let target = source.add_child(
            source.root,
            UiNode::container("target", crate::layout::absolute(0.0, 0.0, 90.0, 40.0))
                .with_input(InputBehavior::BUTTON)
                .with_action("target.activate")
                .with_visual(UiVisual::panel(ColorRgba::new(30, 90, 150, 255), None, 0.0)),
        );
        let mut style = TextStyle::default();
        style.font_size = 14.0;
        style.line_height = 16.0;
        style.wrap = TextWrap::None;
        source.add_child(
            target,
            UiNode::text(
                "target.label",
                "A very long debug label",
                style,
                LayoutStyle::size(48.0, 16.0),
            ),
        );
        source.add_child(
            source.root,
            UiNode::container(
                "cover",
                UiNodeStyle::new(crate::layout::absolute(10.0, 0.0, 90.0, 40.0)).with_z_index(8.0),
            )
            .with_input(InputBehavior::BUTTON)
            .with_action("cover.activate")
            .with_visual(UiVisual::panel(ColorRgba::new(180, 40, 40, 255), None, 0.0)),
        );
        source
            .compute_layout(UiSize::new(220.0, 140.0), &mut ApproxTextMeasurer)
            .expect("source layout");
        let slow_nodes = DebugSlowNodeTrace::from_document(&source, &mut ApproxTextMeasurer);
        let frame = DebugFrameTrace::from_document(
            &source,
            &mut ApproxTextMeasurer,
            crate::debug::DebugFrameTraceContext::new("debug-frame", UiSize::new(220.0, 140.0))
                .timing(
                    FrameTiming::new()
                        .section("layout", std::time::Duration::from_millis(6))
                        .section("render", std::time::Duration::from_millis(18)),
                )
                .timing_budget(std::time::Duration::from_millis(16))
                .dirty_flags(DirtyFlags {
                    layout: true,
                    paint: true,
                    text_measurement: true,
                    ..DirtyFlags::NONE
                }),
        );
        let trace = DebugSlowFrameTrace::from_trace_with_slow_nodes(&frame, &slow_nodes);
        let mut doc = UiDocument::new(root_style(460.0, 260.0));
        let root = doc.root;

        let panel = slow_frame_panel(
            &mut doc,
            root,
            "debug.slow_frame",
            &trace,
            RecordPanelOptions::default().with_action_prefix("debug.slow_frame"),
        );
        doc.compute_layout(UiSize::new(460.0, 260.0), &mut ApproxTextMeasurer)
            .expect("slow frame panel layout");

        assert_eq!(doc.node(panel.root).name, "debug.slow_frame");
        assert!(
            text_content(&doc, "debug.slow_frame.rows.row.summary.value").contains("slow frame")
        );
        assert_eq!(
            text_content(&doc, "debug.slow_frame.rows.row.status.value"),
            "warning"
        );
        assert_eq!(
            text_content(&doc, "debug.slow_frame.rows.row.over_by.value"),
            "8.00ms"
        );
        assert!(
            text_content(&doc, "debug.slow_frame.rows.row.source.timing.value").contains("over by")
        );
        let slow_node_value =
            text_content(&doc, "debug.slow_frame.rows.row.source.slow-node.0.value");
        assert!(
            slow_node_value.contains("sources"),
            "slow frame node row should include source details: {slow_node_value}"
        );
        assert_eq!(
            doc.node(doc.node(panel.rows).children[0])
                .action
                .as_ref()
                .and_then(|action| action.action_id())
                .map(|id| id.as_str()),
            Some("debug.slow_frame.row.summary")
        );
    }

