    #[test]
    fn frame_diff_panel_lists_changed_nodes_and_reasons() {
        let mut before_doc = UiDocument::new(root_style(200.0, 120.0));
        before_doc.add_child(
            before_doc.root,
            UiNode::container("target", LayoutStyle::size(92.0, 36.0))
                .with_input(InputBehavior::BUTTON)
                .with_visual(UiVisual::panel(ColorRgba::new(20, 80, 140, 255), None, 0.0)),
        );
        before_doc
            .compute_layout(UiSize::new(200.0, 120.0), &mut ApproxTextMeasurer)
            .expect("before layout");
        let before = DebugInspectorSnapshot::from_document(&before_doc, &mut ApproxTextMeasurer);

        let mut after_doc = UiDocument::new(root_style(200.0, 120.0));
        after_doc.add_child(
            after_doc.root,
            UiNode::container(
                "target",
                UiNodeStyle::new(crate::layout::absolute(18.0, 0.0, 92.0, 36.0)),
            )
            .with_input(InputBehavior::BUTTON)
            .with_visual(UiVisual::panel(ColorRgba::new(20, 80, 140, 255), None, 0.0)),
        );
        after_doc
            .compute_layout(UiSize::new(200.0, 120.0), &mut ApproxTextMeasurer)
            .expect("after layout");
        let after = DebugInspectorSnapshot::from_document(&after_doc, &mut ApproxTextMeasurer);
        let diff = DebugFrameDiff::from_snapshots(&before, &after);

        let mut doc = UiDocument::new(root_style(380.0, 180.0));
        let root = doc.root;
        let panel = frame_diff_panel(
            &mut doc,
            root,
            "debug.diff",
            &diff,
            ChangePanelOptions::default().with_action_prefix("debug.diff"),
        );
        doc.compute_layout(UiSize::new(380.0, 180.0), &mut ApproxTextMeasurer)
            .expect("diff panel layout");

        assert_eq!(doc.node(panel.root).name, "debug.diff");
        assert_eq!(text_content(&doc, "debug.diff.rows.row.changed.value"), "1");
        assert!(text_content(&doc, "debug.diff.rows.row.node.target.value").contains("layout"));
        assert_eq!(
            doc.node(doc.node(panel.rows).children[0])
                .action
                .as_ref()
                .and_then(|action| action.action_id())
                .map(|id| id.as_str()),
            Some("debug.diff.row.summary")
        );
    }

